// tools/build-bundle.mjs
//
// 把「每页都要加载的那 21 个 JS」合并成一个文件。
//
//   node tools/build-bundle.mjs            # 生成 assets/js/bundle.js
//   node tools/build-bundle.mjs --check    # 只报告是否与源文件一致
//
// 这不是构建步骤的替代品 —— 页面默认仍然逐个引用那 21 个文件。
// bundle 只在用户手动打开开关后才启用（见 assets/js/core/bundle-loader.js）。
// 这样出问题时关掉开关就回到原路径，不需要回滚部署。
//
// 合并顺序由各页面的实际引用顺序决定，不是字母序。顺序错了不会报错，
// 只会让某些功能在某个时机偶发失效 —— 所以顺序写死在 CORE 里，并且
// 每次构建都验证它和页面里的引用顺序一致。

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CHECK_ONLY = process.argv.includes('--check');
const OUT_DIR = path.join(ROOT, 'assets', 'js');
const LOADER = path.join(OUT_DIR, 'bundle-loader.js');

// 顺序 = 44 个页面里实际的加载顺序（已核对完全一致）
const CORE = [
  'arch-render.js',
  'core/ui.js',
  'core/net.js',
  'core/ban-guard.js',
  'core/latex-doc.js',
  'core/status.js',
  'core/script-panel.js',
  'core/api.js',
  'core/padstore.js',
  'core/radial-menu.js',
  'core/ban-screen.js',
  'core/ban-index.js',
  'core/page.js',
  'auth.js',
  'app.js',
  'topbar.js',
  'sidebar.js',
  'core/polling.js',
  'heartbeat.js',
  'pk-invite.js',
  'pk-notify.js',
];

/**
 * 去掉注释，但不动字符串和正则里的内容。
 * 用一个小状态机而不是正则 —— 正则会被 URL 里的 //、字符串里的 /* 骗到。
 */
function stripComments(src) {
  let out = '';
  let i = 0;
  const n = src.length;
  let mode = 'code';           // code | line | block | sq | dq | tpl | regex
  let prevSig = '';            // 上一个有意义字符，用来判断 / 是除号还是正则

  while (i < n) {
    const c = src[i], d = src[i + 1];

    if (mode === 'line') {
      if (c === '\n') { mode = 'code'; out += c; }
      i++;
      continue;
    }
    if (mode === 'block') {
      if (c === '*' && d === '/') { mode = 'code'; i += 2; continue; }
      if (c === '\n') out += c;   // 保留换行，避免把两行粘成一个 token
      i++;
      continue;
    }
    if (mode === 'sq' || mode === 'dq' || mode === 'tpl') {
      out += c;
      if (c === '\\') { out += src[i + 1] ?? ''; i += 2; continue; }
      if ((mode === 'sq' && c === "'") || (mode === 'dq' && c === '"') || (mode === 'tpl' && c === '`')) mode = 'code';
      i++;
      continue;
    }
    if (mode === 'regex') {
      out += c;
      if (c === '\\') { out += src[i + 1] ?? ''; i += 2; continue; }
      if (c === '/') mode = 'code';
      else if (c === '\n') mode = 'code';   // 未闭合的正则，退回代码模式
      i++;
      continue;
    }

    // code 模式
    if (c === '/' && d === '/') { mode = 'line'; i += 2; continue; }
    if (c === '/' && d === '*') { mode = 'block'; i += 2; continue; }
    if (c === "'") { mode = 'sq'; out += c; i++; continue; }
    if (c === '"') { mode = 'dq'; out += c; i++; continue; }
    if (c === '`') { mode = 'tpl'; out += c; i++; continue; }
    if (c === '/') {
      // 除号还是正则：看前一个有意义的字符
      const isRegex = !prevSig || /[=(,:[!&|?{};+\-*%<>~^]/.test(prevSig) || /\b(return|typeof|case|in|of|new|delete|void)\b/.test(out.slice(-12));
      if (isRegex) { mode = 'regex'; out += c; i++; continue; }
      out += c; i++; prevSig = c; continue;
    }
    out += c;
    if (!/\s/.test(c)) prevSig = c;
    i++;
  }
  return out;
}

/** 去掉行首行尾空白，压掉连续空行 —— 但保留换行本身（ASI 靠它） */
function tidy(src) {
  return src
    .split('\n')
    .map(l => l.trimEnd())
    .filter(l => l.length > 0)
    .join('\n');
}

/** 保守单行化：只在确定安全的地方把换行换成空格 */
function oneLine(src) {
  const lines = src.split('\n');
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const cur = lines[i];
    const next = lines[i + 1] ?? '';
    // 这些行末如果直接接下一行，语义可能改变，保留换行
    const risky = /(?:^|[^.\w$])(return|throw|break|continue|yield|await)$/.test(cur.trim())
      || /[+\-*/%&|^<>=!?:,]$/.test(cur.trim())
      || /^(?:else|catch|finally|\}|\]|\))\b/.test(next.trim())
      || /^[([{]/.test(next.trim());
    out.push(cur);
    if (i < lines.length - 1) out.push(risky ? '\n' : ' ');
  }
  return out.join('');
}

// ── 组装 ──
//
// 不做去注释。试过，但一个手写状态机处理不了模板字符串里嵌套的 ${...}
// （topbar.js 里 `...<a href="${...}">...` 这种），会把 HTML 当成代码留下，
// 生成的 bundle 直接语法错误。
//
// 而且这件事本身收益很小：Vercel 对 JS 走 brotli，注释在压缩后几乎不占空间。
// 合并的价值是「21 个请求变 1 个」，不是「少几个字节」。
// 真要做字节级压缩，用 esbuild/terser，别手搓。
const parts = [];
let rawBytes = 0;
for (const rel of CORE) {
  const f = path.join(ROOT, 'assets', 'js', rel);
  if (!fs.existsSync(f)) { console.error(`缺文件: ${rel}`); process.exit(1); }
  const src = fs.readFileSync(f, 'utf8');
  rawBytes += Buffer.byteLength(src);
  parts.push(`/* ${rel} */\n${tidy(src)}`);
}

const banner = `/* moj bundle · ${CORE.length} files · generated by tools/build-bundle.mjs
 * 顺序由页面的实际引用顺序决定，不要手动调整。
 * 关闭方式：localStorage.removeItem('moj:perf:bundle') */
`;
const outText = banner + parts.join('\n;\n') + '\n';
const outBytes = Buffer.byteLength(outText);

// 文件名带内容哈希：vercel.json 给 *.js 配的是 immutable 一年缓存，
// 文件名不变的话改了也不会生效。
const hash = crypto.createHash('sha1').update(outText).digest('hex').slice(0, 10);
const outName = `bundle.${hash}.js`;
const outPath = path.join(OUT_DIR, outName);

// 清掉旧的 bundle.*.js
for (const f of fs.readdirSync(OUT_DIR)) {
  if (/^bundle\.[0-9a-f]{10}\.js$/.test(f) && f !== outName) {
    fs.unlinkSync(path.join(OUT_DIR, f));
    console.log(`删除旧 bundle: ${f}`);
  }
}

fs.writeFileSync(outPath, outText, 'utf8');
console.log(`已写入 ${path.relative(ROOT, outPath)}`);

// 把文件名写进 loader（loader 自己有 ?v= 指纹，所以它的内容一变就会重新下载）
let loader = fs.readFileSync(LOADER, 'utf8');
const patched = loader.replace(/var BUNDLE_FILE = '[^']*';/, `var BUNDLE_FILE = '${outName}';`);
if (patched !== loader) {
  fs.writeFileSync(LOADER, patched, 'utf8');
  console.log(`loader 指向 ${outName}`);
} else {
  console.log('loader 已是目标文件名');
}
